// ── Animations ───────────────────────────────────────────────────────────────

const floatUp = keyframes`
  0%   { transform: translateY(0)      rotate(0deg);   opacity: 0.8; }
  100% { transform: translateY(-100vh) rotate(360deg); opacity: 0;   }
`;

const shimmer = keyframes`
  0%   { background-position: -300% center; }
  100% { background-position:  300% center; }
`;

const spinConic = keyframes`
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
`;

const discoGlow = keyframes`
  0%,100% { box-shadow: 0 0 40px 10px rgba(255,215,0,0.55),  0 12px 80px rgba(0,0,0,0.6); }
  16%     { box-shadow: 0 0 40px 10px rgba(255,80,180,0.55),  0 12px 80px rgba(0,0,0,0.6); }
  33%     { box-shadow: 0 0 40px 10px rgba(80,200,255,0.55),  0 12px 80px rgba(0,0,0,0.6); }
  50%     { box-shadow: 0 0 40px 10px rgba(120,255,120,0.55), 0 12px 80px rgba(0,0,0,0.6); }
  66%     { box-shadow: 0 0 40px 10px rgba(255,140,40,0.55),  0 12px 80px rgba(0,0,0,0.6); }
  83%     { box-shadow: 0 0 40px 10px rgba(180,80,255,0.55),  0 12px 80px rgba(0,0,0,0.6); }
`;

const floatA = keyframes`
  0%,100% { transform: translateY(0px)  rotate(0deg); }
  50%     { transform: translateY(-22px) rotate(1deg); }
`;

const floatB = keyframes`
  0%,100% { transform: translateY(0px)  rotate(0deg); }
  50%     { transform: translateY(16px)  rotate(-1deg); }
`;

const floatC = keyframes`
  0%,100% { transform: translateY(-8px)  rotate(0deg); }
  50%     { transform: translateY(10px)  rotate(0.5deg); }
`;

const dotBlink = keyframes`
  0%,100% { opacity: 1; }
  50%      { opacity: 0.3; }
`;

const drainBar = keyframes`
  from { width: 100%; }
  to   { width: 0%; }
`;

const cardIn = keyframes`
  from { opacity: 0; transform: scale(0.96) translateY(16px); }
  to   { opacity: 1; transform: scale(1)    translateY(0); }
`;

const sparkle = keyframes`
  0%,100% { opacity: 0; transform: scale(0.5) rotate(0deg); }
  50%     { opacity: 1; transform: scale(1.2) rotate(180deg); }
`;

