// ── Helpers ───────────────────────────────────────────────────────────────────

function relativeTime(iso) {
  const diff = Math.floor((Date.now() - new Date(iso)) / 1000);
  if (diff < 60) return "just now";
  if (diff < 3600) return `${Math.floor(diff / 60)}m ago`;
  return `${Math.floor(diff / 3600)}h ago`;
}

// ── Component ─────────────────────────────────────────────────────────────────

const DisplayPage = () => {
  const [token, setToken]         = useState(null);
  const [event, setEvent]         = useState(null);
  const [pageState, setPageState] = useState("loading");
  const [mounted, setMounted]     = useState(false);

  const [items, setItems]         = useState([]);
  const [currentIdx, setCurrentIdx] = useState(0);
  const [visible, setVisible]     = useState(true);
  const cycleRef = useRef(null);

  // Transition to a new item with fade
  const showItem = useCallback((idx) => {
    setVisible(false);
    setTimeout(() => {
      setCurrentIdx(idx);
      setVisible(true);
    }, 450);
  }, []);

  // Prepend a new item and immediately show it
  const addItem = useCallback((item) => {
    setVisible(false);
    setTimeout(() => {
      setItems(prev => {
        if (prev.some(p => p.id === item.id)) return prev;
        return [item, ...prev];
      });
      setCurrentIdx(0);
      setVisible(true);
    }, 450);
  }, []);

  // Auto-cycle every 10 seconds
  useEffect(() => {
    clearTimeout(cycleRef.current);
    cycleRef.current = setTimeout(() => {
      setItems(prev => {
        if (prev.length <= 1) return prev;
        const nextIdx = (currentIdx + 1) % prev.length;
        showItem(nextIdx);
        return prev;
      });
    }, 10000);
    return () => clearTimeout(cycleRef.current);
  }, [currentIdx, showItem]);

  // Realtime channel
  useEventChannel({
    eventId: event?.id,
    enabled: Boolean(event?.id),
    onPhoto: (payload) => addItem({
      type: "photo",
      id: payload.photoId,
      guestName: payload.guestName,
      publicUrl: payload.publicUrl,
      text: payload.message || null,
      createdAt: payload.createdAt,
    }),
    onMessage: (payload) => addItem({
      type: "message",
      id: payload.messageId,
      guestName: payload.guestName,
      text: payload.message,
      createdAt: payload.createdAt,
    }),
  });

  // Bootstrap
  useEffect(() => {
    setMounted(true);
    if (typeof window === "undefined") return;
    const params = new URLSearchParams(window.location.search);
    const eid = params.get("eid");

    if (!eid) { setPageState("mock"); return; }
    setToken(eid);

    const client = getSupabaseClient();
    if (!client) { setPageState("mock"); return; }

    client.rpc("get_event_by_token", { p_token: eid }).then(({ data, error }) => {
      if (error || !data || data.length === 0) { setPageState("error"); return; }
      const ev = data[0];
      setEvent(ev);

      // Load recent photos as initial items
      client.rpc("get_event_photos", { p_token: eid, p_limit: 30 }).then(({ data: photos }) => {
        if (photos) {
          setItems(photos.map(p => ({
            type: "photo",
            id: p.id,
            guestName: p.guest_name,
            publicUrl: getPublicUrl(p.storage_path),
            text: p.message || null,
            createdAt: p.created_at,
          })));
        }
        setPageState("ready");
      });
    });
  }, []);

  useEffect(() => {
    if (pageState === "mock") setItems(MOCK_ITEMS);
  }, [pageState]);

  const isMock  = pageState === "mock";
  const isReady = pageState === "ready" || isMock;
  const currentItem = items[currentIdx] ?? null;

  return (
    <>
      <Fonts />
      <Helmet title="Sweet Seventy, Elvie! 🪩" />
      <Page>
        {/* Elvie photo background */}
        <ElvieImg src="/elvie.png" alt="" />
        <DarkVignette />

        {/* Disco balls */}
        {mounted && BALLS.map((b, i) => (
          <BallFloat
            key={i}
            $float={b.float}
            $fd={b.fd}
            $op={b.opacity}
            style={{ top: b.top, left: b.left, right: b.right }}
          >
            <BallSphere $s={b.size} $dur={b.dur} $cd={b.cd} />
          </BallFloat>
        ))}

        {/* Confetti */}
        {mounted && (
          <ParticleLayer>
            {PARTICLES.map((p, i) => (
              <Particle key={i} $left={p.left} $size={p.size} $delay={p.delay} $dur={p.dur} $color={p.color} />
            ))}
            {SPARKLES.map((s, i) => (
              <SparkleEl key={i} $top={s.top} $left={s.left} $dur={s.dur} $delay={s.delay}>✦</SparkleEl>
            ))}
          </ParticleLayer>
        )}

        {/* UI */}
        <ContentLayer>
          <Header>
            <span style={{ fontSize: "1.3rem", filter: "drop-shadow(0 0 10px rgba(255,215,0,0.7))" }}>🪩</span>
            <MainTitle>Sweet Seventy, Elvie!</MainTitle>
            <TagLine>Every moment, captured live ✦</TagLine>
            {(isMock || event?.active) && (
              <LiveBadge><LiveDot />Live</LiveBadge>
            )}
          </Header>

          <Stage>
            {pageState === "loading" && (
              <p style={{ color: "rgba(255,220,100,0.3)", fontWeight: 300 }}>Loading…</p>
            )}
            {pageState === "error" && (
              <p style={{ color: "rgba(255,220,100,0.3)", fontWeight: 300 }}>Event not found.</p>
            )}

            {isReady && currentItem && (
              <GlassCard $vis={visible}>
                {currentItem.type === "message" ? (
                  <MsgSlide>
                    <QuoteMark>"</QuoteMark>
                    <MsgText>{currentItem.text}</MsgText>
                    <MsgFooter>
                      <MsgAuthor>— {currentItem.guestName}</MsgAuthor>
                      <MsgTime>{relativeTime(currentItem.createdAt)}</MsgTime>
                    </MsgFooter>
                  </MsgSlide>
                ) : (
                  <PhotoSlide>
                    <SlideImg src={currentItem.publicUrl} alt={currentItem.guestName ?? "photo"} />
                    <SlideCaption>
                      <SlideName>{currentItem.guestName}</SlideName>
                      {currentItem.text && <SlideMsg>"{currentItem.text}"</SlideMsg>}
                      <SlideTime>{relativeTime(currentItem.createdAt)}</SlideTime>
                    </SlideCaption>
                  </PhotoSlide>
                )}
                {/* Key ensures animation restarts on each new item */}
                <ProgressBar key={`${currentIdx}-${currentItem.id}`} />
              </GlassCard>
            )}

            {isReady && items.length === 0 && (
              <GlassCard $vis={visible}>
                <MsgSlide>
                  <MsgText style={{ fontSize: "1rem", color: "rgba(255,255,255,0.4)" }}>
                    Photos and messages from guests will appear here.
                  </MsgText>
                </MsgSlide>
              </GlassCard>
            )}
          </Stage>
        </ContentLayer>
      </Page>
    </>
  );
};

export default DisplayPage;
